const timeline: TimelineItem[] = [
  { year: "Abad 10–11", era: "Cikal bakal", title: "Prasasti awal Panjalu", short: "Nama Panjalu mulai berjejak dalam perubahan politik Jawa Timur.", detail: "Sejumlah prasasti dari Jawa Timur menjadi petunjuk penting untuk memahami masa peralihan setelah Kahuripan. Prasasti Sirah Keting (1104 M) merekam jejak pemerintahan Sri Jayawarsa di wilayah Panjalu.", detail2: "Fragmen batu dan aksara menjadi pintu masuk untuk membaca cara masyarakat menata kuasa, wilayah, dan ingatan sebelum Kediri mencapai masa kejayaannya.", image: imageDb.tondowongso.image, alt: imageDb.tondowongso.alt, accent: "#d5a55e" },
  { year: "1042", era: "Pembelahan Kahuripan", title: "Lahirnya Panjalu & Jenggala", short: "Airlangga membagi wilayah kerajaan; dua nama besar tumbuh dari satu akar.", detail: "Untuk menghindari perebutan takhta, Airlangga membagi wilayah kerajaannya menjadi Panjalu (Kediri) dan Jenggala. Sejak saat itu, Panjalu berkembang sebagai kekuatan politik penting di Jawa Timur.", detail2: "Pembelahan ini menjadi titik yang membuat nama Panjalu dan Kediri hadir sebagai identitas politik yang terus dikenang dalam sejarah Jawa.", image: imageDb.brantas.image, alt: imageDb.brantas.alt, accent: "#81a66b" },
  { year: "1135–1157", era: "Masa keemasan", title: "Jayabaya & sastra Panjalu", short: "Perdagangan ramai, karya sastra tumbuh, dan Jayabaya dikenang lintas zaman.", detail: "Pada masa Sri Jayabaya, Panjalu dikenal makmur. Kakawin Bharatayuddha disusun oleh Mpu Sedah dan Mpu Panuluh pada 1157 M. Karena foto Prasasti Hantang dan petilasan Jayabaya belum memiliki sumber bebas pakai yang terverifikasi, arsip Museum Airlangga dipakai sebagai pintu masuk konteks artefak Kediri.", detail2: "Sungai Brantas menghubungkan ruang produksi, pasar, dan pusat kekuasaan. Sejarah Kediri ditulis lewat sastra, bukan hanya lewat perang.", image: imageDb.museumAirlangga.image, alt: imageDb.museumAirlangga.alt, accent: "#c7744f" },
  { year: "1222", era: "Peralihan kuasa", title: "Ganter & berakhirnya Panjalu", short: "Pertempuran Ganter membuka jalan bagi Singhasari di bawah Ken Arok.", detail: "Konflik antara Kertajaya dan Ken Arok berujung pada Pertempuran Ganter. Kekalahan Kediri menandai berakhirnya kerajaan Panjalu sebagai pusat kuasa, namun identitas dan jejak budayanya tetap berlanjut.", detail2: "Foto Goa Selomangleng menampilkan situs arkeologi Kediri yang nyata sebagai konteks kesinambungan ruang, bukan rekonstruksi pertempuran Ganter.", image: imageDb.selomangleng.image, alt: imageDb.selomangleng.alt, accent: "#aa5f49" },
  { year: "Abad 13", era: "Masa transisi", title: "Kediri di antara Singhasari", short: "Wilayah Kediri beradaptasi saat pusat kuasa Jawa Timur bergeser.", detail: "Setelah 1222, Kediri tidak hilang dari peta kebudayaan. Wilayahnya menjadi ruang perlintasan politik, ekonomi, dan keagamaan yang terhubung dengan pusat-pusat baru di Jawa Timur.", detail2: "Masa transisi mengajarkan bahwa sejarah tidak berhenti ketika sebuah kerajaan tumbang. Jejak masyarakat terus menyusun cerita baru di tempat yang sama.", image: historic.brantas, alt: "Sungai Brantas di Kota Kediri sebagai lanskap transisi politik dan ekonomi, Wikimedia Commons CC BY-SA 3.0", accent: "#d5a55e" },
  { year: "Abad 14", era: "Majapahit", title: "Kediri dalam jejaring Majapahit", short: "Kediri tetap penting sebagai ruang budaya dan wilayah strategis.", detail: "Dalam jejaring Majapahit, wilayah Kediri tetap menjadi ruang produksi budaya dan jalur penting di sekitar Brantas. Candi Tegowangi menjadi penanda lapisan sejarah ini.", detail2: "Bangunan candi menyimpan hubungan antara kuasa, ritual, seni, dan kisah yang hidup di tengah masyarakat.", image: imageDb.tegowangi.image, alt: imageDb.tegowangi.alt, accent: "#81a66b" },
  { year: "Abad 15", era: "Kadipaten & kisah Panji", title: "Candi Surowono & Tegowangi", short: "Kisah Panji dan relief candi meninggalkan bahasa visual yang khas.", detail: "Candi Surowono dan Tegowangi menjadi pengingat kuat dari lanskap politik serta keagamaan masa Majapahit di Kediri. Reliefnya membantu kita membaca cara masyarakat bercerita melalui batu.", detail2: "Kisah Panji dan Sudamala mempertemukan seni, nilai moral, dan ritual. Situs-situs ini mengajak kita melihat sejarah dari detail kecil yang tersisa.", image: imageDb.surowono.image, alt: imageDb.surowono.alt, accent: "#c7744f" },
  { year: "Abad 19", era: "Kota & industri gula", title: "Jalur baru, kota baru", short: "Perkebunan, pabrik gula, dan kereta mengubah wajah Kediri.", detail: "Perkebunan tebu, pabrik gula, dan jalur kereta membentuk ritme ekonomi baru pada masa kolonial. Kota dan kabupaten berkembang sebagai simpul perdagangan.", detail2: "Jejak masa ini masih terasa pada pola kota, ekonomi pertanian, dan ingatan keluarga yang diwariskan lintas generasi.", image: imageDb.station.image, alt: imageDb.station.alt, accent: "#d5a55e" },
  { year: "1908–1945", era: "Pergerakan nasional", title: "Kediri dalam arus kebangsaan", short: "Pendidikan, organisasi, dan kabar kemerdekaan menemukan ruang di Kediri.", detail: "Gagasan kebangsaan bergerak melalui sekolah, organisasi, pers, dan jaringan perdagangan. Kediri menjadi bagian dari arus pergerakan yang menghubungkan daerah dengan cita-cita Indonesia.", detail2: "Arsip Jembatan Lama menjadi dokumen kota yang memperlihatkan infrastruktur dan ruang perjumpaan Kediri pada masa kolonial.", image: imageDb.bridge.image, alt: imageDb.bridge.alt, accent: "#aa5f49" },
  { year: "1945–1966", era: "Indonesia awal", title: "Menata kehidupan baru", short: "Kediri menata administrasi, pendidikan, dan ekonomi setelah kemerdekaan.", detail: "Sesudah kemerdekaan, Kediri menata diri sebagai bagian dari Indonesia modern. Pendidikan, perdagangan, pertanian, dan ruang publik menjadi fondasi kehidupan baru.", detail2: "Foto Jembatan Brawijaya dipakai untuk menandai kesinambungan pembangunan ruang kota Kediri; arsip spesifik gedung pemerintahan pascakemerdekaan belum tersedia dengan sumber bebas pakai.", image: imageDb.brawijaya.image, alt: imageDb.brawijaya.alt, accent: "#81a66b" },
  { year: "1966–1998", era: "Orde Baru", title: "Industri, jalan, dan pertumbuhan", short: "Pembangunan dan industri mempercepat perubahan wajah Kediri.", detail: "Pada masa Orde Baru, industri, infrastruktur, dan perluasan pendidikan ikut membentuk ritme baru Kediri. Pertumbuhan membawa peluang sekaligus perubahan sosial.", detail2: "Sungai Brantas tetap menjadi koridor nyata yang menghubungkan perkembangan kota, jalur ekonomi, serta kenangan warga yang mengalami perubahan dari dekat.", image: imageDb.brantas.image, alt: imageDb.brantas.alt, accent: "#c7744f" },
  { year: "Kini", era: "Kediri modern", title: "Merawat akar, membuka jalan", short: "SLG, Kampung Inggris, Kelud, dan kuliner membuat Kediri terus bercerita.", detail: "Hari ini, Kota dan Kabupaten Kediri bergerak sebagai ruang pendidikan, industri, wisata, dan budaya. Monumen Simpang Lima Gumul, Kampung Inggris Pare, Gunung Kelud, dan ragam kulinernya menyambungkan warisan dengan masa depan.", detail2: "Menjadi modern tidak berarti meninggalkan akar. Tantangannya adalah membuat situs, tradisi, dan rasa lokal tetap relevan bagi generasi yang hidup dengan cara baru.", image: historic.slg, alt: "Monumen Simpang Lima Gumul Kediri masa kini, Wikimedia Commons CC BY 4.0", accent: "#d5a55e" },
];

